import random
random.seed(42)

target = "(((((....)).((((((....)))..((((.((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).))))..(((....)))))).((....)))))"
n = len(target)

# Parse pairs
stack = []
tpairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        tpairs[i] = j
        tpairs[j] = i

# Parse stems
stems = []
i = 0
while i < n:
    if i in tpairs and target[i] == '(':
        open_pos = []
        while i < n and i in tpairs and target[i] == '(':
            open_pos.append(i)
            i += 1
        close_pos = sorted([tpairs[op] for op in open_pos])
        stems.append({'open': open_pos, 'close': close_pos})
    else:
        i += 1

# Find hairpin loops (between last open and first close)
hairpins = []
for s in stems:
    last_open = s['open'][-1]
    first_close = s['close'][0]
    if first_close - last_open > 1 and all(target[k] == '.' for k in range(last_open+1, first_close)):
        hairpins.append({
            'start': last_open + 1,
            'end': first_close,
            'len': first_close - last_open - 1,
            'closing_pair': (last_open, first_close)
        })

print(f"Hairpins: {len(hairpins)}")

# Motif library for hairpins
motif_4 = ['GAAA', 'UUCG', 'GCAA', 'CUUG', 'GAGA', 'GUGA', 'GGAA', 'UACG']
motif_3 = ['GAA', 'UUC', 'CUU', 'GUA', 'UUA', 'AAA']
motif_2 = ['GA', 'UU', 'AA', 'GU', 'CA', 'AU']
motif_1 = ['A', 'U', 'G', 'C']

def get_motif(loop_len, idx):
    if loop_len == 4:
        return motif_4[idx % len(motif_4)]
    elif loop_len == 3:
        return motif_3[idx % len(motif_3)]
    elif loop_len == 2:
        return motif_2[idx % len(motif_2)]
    elif loop_len == 1:
        return motif_1[idx % len(motif_1)]
    else:
        return 'A' * loop_len

# Pair type pool - each pair gets a type
pair_types = ['GC', 'CG', 'AU', 'UA', 'GU', 'UG']

def gen_candidate():
    seq = ['A'] * n

    # Assign each pair: use unique pair types per stem position
    for si, s in enumerate(stems):
        for k, (o, c) in enumerate(zip(s['open'], s['close'])):
            # Unique assignment: use (stem_idx * 7 + pos_in_stem * 3) % 6
            pt_idx = (si * 7 + k * 3) % 6
            pt = pair_types[pt_idx]
            seq[o] = pt[0]
            seq[c] = pt[1]

    # Assign loop sequences
    for hi, h in enumerate(hairpins):
        motif = get_motif(h['len'], hi)
        for k in range(h['len']):
            seq[h['start'] + k] = motif[k]

    # Other unpaired: use varied bases
    for i in range(n):
        if seq[i] == 'A' and target[i] == '.':
            seq[i] = random.choice('AU')

    return ''.join(seq)

# Generate 4000 diverse candidates
candidates = []
for _ in range(4000):
    candidates.append(gen_candidate())

# Write to file
with open('/tmp/candidates2.txt', 'w') as f:
    for seq in candidates:
        f.write(seq + '\n')

print(f"Generated {len(candidates)} candidates")
print(f"Sample: {candidates[0][:80]}...")
